/**
 * The demo user: real nights from two public datasets, re-dated so that the last
 * night in the file is last night. Generated by `pipeline/build_demo_user.py`.
 *
 * It is a composite of two different people, so every field records which dataset
 * it came from. Analyses that link one field to another (e.g. alcohol -> HRV) must
 * check `sameParticipant` first; linking across people would invent a pattern.
 */

import demoUser from './demo/demo-user.json';
import type { NightSummary, SleepSegment, SleepStage } from './types';

export type DemoSource = keyof typeof demoUser.meta.sources;

export type DemoField =
  'sleep' | 'restingHr' | 'self' | 'behaviors' | 'hrvMs' | 'respiratoryRate' | 'wristTempDeltaC';

export type DemoNight = (typeof demoUser.nights)[number];

export const DEMO_META = demoUser.meta;

/** HRV metric and device for labels, e.g. "HRV (RMSSD)" and "Fitbit". */
export const HRV_METRIC = demoUser.meta.hrvMetric;
export const DEVICE_LABEL = demoUser.meta.device;

export function sourceOf(field: DemoField): DemoSource {
  for (const [source, info] of Object.entries(demoUser.meta.sources)) {
    if ((info.fields as string[]).includes(field)) return source as DemoSource;
  }
  throw new Error(`No source recorded for ${field}`);
}

/** Whether two fields were measured on the same person, so they can be compared. */
export function sameParticipant(a: DemoField, b: DemoField) {
  return sourceOf(a) === sourceOf(b);
}

function addMinutes(date: Date, minutes: number) {
  return new Date(date.getTime() + minutes * 60_000);
}

/** The morning a demo night ends on, relative to today. */
export function wakeDateOf(night: DemoNight) {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  date.setDate(date.getDate() + night.offset);
  return date;
}

export function summarize(night: DemoNight): NightSummary {
  const wakeDate = wakeDateOf(night);
  const inBedStart = addMinutes(wakeDate, night.bedMin);
  const segments: SleepSegment[] = night.segments.map(([stage, start, duration]) => ({
    stage: stage as SleepStage,
    start: addMinutes(inBedStart, start as number),
    end: addMinutes(inBedStart, (start as number) + (duration as number)),
  }));
  return {
    wakeDate,
    inBedStart,
    inBedEnd: addMinutes(wakeDate, night.outMin),
    segments,
    wakings: night.wakings,
    awakeMinutes: night.awakeMin,
    hrvMs: night.hrvMs,
    restingHr: night.restingHr,
    respiratoryRate: night.respiratoryRate,
    wristTempDeltaC: night.wristTempDeltaC,
  };
}

export const demoNights: DemoNight[] = demoUser.nights;

/** Shown wherever demo data is on screen, so nobody mistakes it for one real person. */
export const DEMO_NOTE = `Demo data: sleep, journal and habits from PMData (participant ${demoUser.meta.sources.pmdata.participant}); HRV, breathing and temperature from LifeSnaps. Real nights from two public datasets, re-dated to the last ${demoUser.meta.nights} days.`;

export const lastNight: NightSummary = summarize(demoNights[demoNights.length - 1]);
